"""作业 7：价值函数近似与梯度下降，截图转录及独立解答。"""
def get_questions(p, f, ul):
    return [
    (7,1,'欠拟合的含义','在函数拟合中，欠拟合指：',
    ['模型过于复杂，导致在训练集上表现很好，但在测试集上表现较差','模型无法捕捉到数据中的复杂关系，表现出过于简单的形式','模型的参数数量过多，导致训练困难','模型的损失函数出现了局部最优解'],1,
    p('答案为 B。欠拟合（underfitting）指模型未能充分学习数据的规律，通常连训练数据都拟合不好。例如真实关系为明显的曲线，却只能用直线表达，就可能出现欠拟合。') +
    ul('A 描述过拟合：训练集表现好，但泛化到新数据较差。','B 描述模型表达过于简单、未捕获复杂关系，符合欠拟合。','C 是参数规模与优化难度的问题，不是欠拟合的定义。','D 是优化问题；局部最优与欠拟合并不是同义词。'),
    '表达能力、优化与泛化要分开判断',p('训练误差较高时，原因可能是模型容量不足、特征缺少信息、正则化过强或训练未充分收敛。应先检查训练与验证误差，再决定增加表达能力、改进特征或调整优化过程。') +
    p('训练误差低而验证误差明显高，更像过拟合。增大网络并不保证改善效果；验证集也应与实际应用场景相匹配，避免数据泄漏。')),
    (7,2,'激活函数的作用','在神经网络中，激活函数的作用是什么？',['进行数据预处理','约束权重参数的范围','增加非线性','减少过拟合'],2,
    p('答案为 C。非线性激活函数使多层网络能够表达复杂的非线性映射。若每一层都只有仿射变换，多层复合仍可合并成一个仿射变换。') +
    f('W₂(W₁x + b₁) + b₂ = (W₂W₁)x + (W₂b₁ + b₂)') +
    p('加入 ReLU、tanh 等非线性函数后，一般就不能再这样合并。数据预处理、权重约束和减少过拟合分别有其他专门方法，不是激活函数在本题中的主要作用。'),
    '价值网络的输出层常采用线性输出',p('隐藏层需要非线性，并不意味着输出层也必须用非线性。价值可能为负，也可能大于 1；若没有额外的价值范围设计，输出层常采用线性输出。盲目使用 sigmoid 会把预测限制在 (0,1)。') +
    p('例如 ReLU(x)=max(0,x)，适合许多隐藏层，但也可能产生长期不激活的单元。激活函数的选择会影响梯度传播，不能把它当作自动消除过拟合的机制。')),
    (7,3,'价值近似网络的输入','在价值函数近似中，如果使用神经网络作为价值函数的近似模型，那么神经网络的输入通常是什么？',
    ['状态特征','动作特征','状态和动作特征的组合','状态和时间步的组合'],(0,2),
    '<p class="note">建议答案为 A、C，按通常的平稳 V(s) / Q(s,a) 近似语境作答。题目未限定时域：有限时域或时间依赖任务中，D 也可以是合理输入，因此不能把 D 说成在所有任务中都错误。</p>' +
    ul('<b>A：</b>状态价值网络 V̂(s;θ) 输入状态特征，输出该状态的价值。离散动作的 Q 网络也可只输入状态，一次输出各个动作的 Q 值。','<b>B：</b>仅输入动作通常无法区分同一动作在不同状态下的后果，不是一般 MDP 中的完整价值输入。','<b>C：</b>动作价值网络 Q̂(s,a;θ) 可以联合输入状态与动作特征，输出这个状态—动作对的价值。','<b>D：</b>若价值显式依赖剩余时间，可以输入状态与时间；在默认平稳且状态信息充分的设定中，通常无需另外输入时间步。') +
    f('状态价值：φ(s) → V̂(s;θ)<br>动作价值：φ(s,a) → Q̂(s,a;θ)<br>离散动作多输出：φ(s) → [Q̂(s,a₁), …, Q̂(s,aₖ)]'),
    '有限时域为什么可能需要时间？',p('同样的位置，距离截止时间还有 10 步与只剩 1 步时，可获得的回报可能不同。因此可学习 V̂(s,t) 或把剩余时间并入状态。若状态已经包含时间，就不必重复增加同一特征。') +
    p('这是一处题目语境歧义，保留 A、C 作为常规建议答案，并注明 D 的条件。参考：<a href="https://spinningup.openai.com/en/latest/spinningup/rl_intro.html">Spinning Up：价值函数与有限时域的时间依赖</a>。')),
    (7,4,'价值函数的作用','在强化学习中，价值函数的作用是什么？',['用于描述状态的特征','用于描述动作的特征','用于描述状态或动作的价值','用于描述状态转移的概率'],2,
    p('答案为 C。价值函数衡量从某个状态或状态—动作对出发，按指定策略继续行动时能够获得的期望回报，或衡量最优策略下的期望回报。') +
    f('V<sup>π</sup>(s) = E<sub>π</sub>[Gₜ | Sₜ=s]<br>Q<sup>π</sup>(s,a) = E<sub>π</sub>[Gₜ | Sₜ=s, Aₜ=a]') +
    p('状态与动作的特征是输入表示，转移概率 P(s′|s,a) 描述环境动力学；它们与价值函数不是同一个对象。题目中“动作的价值”更准确地指某状态下执行该动作的长期价值。'),
    '奖励、价值与策略的关系',p('奖励是一步反馈，价值考虑未来累积结果，策略决定怎样选动作。当前奖励高的动作未必长期价值高。对于固定策略，价值依赖该策略；最优价值则对可选策略取最优。') +
    p('价值函数近似用共享参数替代逐状态查表，可在相似状态之间泛化。但一个参数更新也可能同时改变多个状态的预测，因而既带来样本利用优势，也引入相互干扰。')),
    (7,5,'学习率过大的影响','随机梯度下降中，学习率过大会导致什么？',['模型过拟合','算法不稳定','收敛速度快','模型欠拟合'],1,
    p('答案为 B。学习率过大时，一次更新可能跨过合适的低损失区域，造成震荡甚至发散，尤其在梯度噪声或曲率较大时。不能据此保证收敛更快。') +
    f('θₖ₊₁ = θₖ − α∇L(θₖ)') +
    p('考虑简单损失 L(w)=w²/2，其梯度为 w，更新变为 wₖ₊₁=(1−α)wₖ。当 α=0.5 时，w 每次减半；α=2 时，非零 w 在正负之间振荡而不衰减；α=3 时，绝对值每次加倍。这个例子说明大步长会破坏稳定性。'),
    '稳定范围取决于问题尺度',p('上例 0&lt;α&lt;2 的收敛范围只适用于该特定二次损失，不能当作所有网络的通用学习率范围。输入尺度、损失曲率、批量大小和优化器都会影响可用步长。') +
    p('过拟合与欠拟合描述拟合及泛化表现；“学习率过大”的直接问题是优化不稳定，而不是必然属于其中某一种。可以结合损失曲线检查震荡，再调整学习率或梯度尺度。')),
    (7,6,'学习率是什么','随机梯度下降中的学习率是什么？',['更新步长','损失函数','正则化项','训练样本数量'],0,
    p('答案为 A。学习率 α 控制沿负梯度方向更新参数的尺度。损失函数决定优化目标，正则化项可以作为损失的一部分，样本数量则属于数据规模。') +
    f('θ ← θ − αĝ<br>实际参数变化 Δθ = −αĝ') +
    p('例如当前参数 w=2，梯度估计 ĝ=3，α=0.1，则更新后 w=2−0.1×3=1.7。相同梯度下，学习率越大，更新幅度越大。'),
    '“步长”不等于固定的移动距离',p('实际更新距离为 α‖ĝ‖，还取决于梯度大小；学习率本身不是每次固定走多远。SGD 用样本或小批量梯度估计整体梯度，因此每一步方向可能带噪声。') +
    p('学习率可以固定、按计划衰减或由优化器进行适应性调整。α 与强化学习中的折扣因子 γ、迹参数 λ 控制不同的事情，不应混淆。')),
    (7,7,'梯度下降的步骤顺序','梯度下降算法的正确步骤是什么？<br>a. 计算预测值和真实值之间的误差<br>b. 重复迭代，直至得到网络权重的最佳值<br>c. 把输入传入网络，得到输出值<br>d. 用随机值初始化权重和偏差<br>e. 对每一个产生误差的神经元，调整相应的（权重）值以减小误差',
    ['abcde','edcba','cbaed','dcaeb'],3,
    p('答案为 D，d → c → a → e → b。先初始化参数，再前向计算预测，计算损失，通过反向传播求梯度并更新参数，然后重复前向、损失计算与更新过程。') +
    f('d 初始化 → c 前向传播 → a 计算误差 / 损失 → e 求梯度并更新 → b 重复迭代') +
    p('没有先得到输出就不能比较预测与目标；没有误差及梯度就无法进行有依据的参数更新。初始化通常只做一次，不是在每轮训练时重新随机化。'),
    '原题的教学简写与实际实现',p('e 的准确含义是利用链式法则计算损失对可训练参数的梯度，再更新权重及偏置，并不是给每个神经元独立指定一个“正确输出”。反向传播负责计算梯度，梯度下降负责用梯度更新参数。') +
    p('d 是典型初始化描述：常对权重采用合适的随机初始化以打破对称，偏置可以初始化为 0，不要求所有偏置都随机。b 中“最佳值”也不是全局最优保证；实际按验证表现、迭代预算或收敛判据停止。')),
    (7,8,'价值近似的常用损失','价值函数近似中最常用的损失函数是？',['交叉熵损失函数','平均绝对误差损失','均方差损失函数','0-1 损失函数'],2,
    p('答案为 C。原选项写“均方差损失函数”，此处按通常教材含义解释为均方误差损失 MSE。价值预测是数值回归，经常用预测与回报目标之间的平方误差训练。') +
    f('L(θ) = (1/N) ∑<sub>i=1</sub><sup>N</sup> [yᵢ − V̂(sᵢ;θ)]²') +
    p('例如预测为 2、4，目标为 3、2，则 MSE=[(3−2)²+(2−4)²]/2=2.5。交叉熵与 0-1 损失通常用于分类；平均绝对误差也可用于回归，但不是本题预期的经典平方误差形式。'),
    'MSE、半平方误差与 Huber 损失',p('推导中也常用 L=(y−V̂)²/2，其中 1/2 消去求导时的系数 2，不改变同一固定数据问题的最优解，但在固定学习率下会改变梯度尺度。MSE 是相对目标的误差平方均值，不是预测值自身的方差。') +
    p('平方损失对大误差较敏感，实践中也会用 Huber 损失减弱极端误差的影响。因此“常用 MSE”不等于“只能用 MSE”。损失形式与目标来源是两回事：MC 与 TD 都能采用平方损失，但目标不同。')),
    (7,9,'MC 使用什么学习目标','要进行梯度下降需要一个目标值，蒙特卡洛方法使用了 TD 目标作为这个目标值。',['对','错'],1,
    p('答案为 B，错。本题讨论价值回归时，经典蒙特卡洛方法使用完整采样回报 Gₜ 作为目标；一步 TD 使用即时奖励与后继价值估计构成的自举目标。') +
    f('MC：yₜ = Gₜ = Rₜ₊₁ + γRₜ₊₂ + ⋯<br>TD(0)：yₜ = Rₜ₊₁ + γV̂(Sₜ₊₁;θ)') +
    p('例如 γ=0.9，后续奖励依次为 1、2 并终止，MC 的目标是 1+0.9×2=2.8。若当前网络估计下一状态价值为 5，TD 目标为 1+0.9×5=5.5。二者可能不同，因为 TD 使用了尚不准确的价值估计。'),
    '半梯度与目标值的语境',p('对单样本半平方损失，若把目标 y 视为固定值，更新为：') +
    f('θ ← θ + α[y − V̂(Sₜ;θ)]∇<sub>θ</sub>V̂(Sₜ;θ)') +
    p('MC 的已观测回报不依赖价值网络参数。经典半梯度 TD 则在构造目标后，不通过目标中的后继价值反向传播；这与对目标和预测两端都求导不同。真正终止时，TD 目标不再包含未来价值。') +
    p('原题前半句“梯度下降需要一个目标值”应限于此处的监督式价值拟合。一般梯度下降只需要可优化的目标函数，并不一定需要每个样本的标注目标值。参考：<a href="https://hankyang.seas.harvard.edu/OptimalControlReinforcementLearning/value-rl.html">价值函数近似中的 MC 与半梯度 TD</a>。')),
    ]

RECAP = '''<section id="approx-recap"><div class="eyebrow">FUNCTION APPROXIMATION / 复习卡</div><h2>把价值学习写成函数拟合</h2><div class="concepts"><p><b>表示</b><br>状态或状态—动作特征 → 价值预测</p><p><b>目标</b><br>MC：完整回报<br>TD：奖励 + 后继估计</p><p><b>优化</b><br>计算损失 → 反向求梯度 → 更新参数</p></div><table><caption>第 7 次作业 · 易考判断</caption><thead><tr><th>说法</th><th>判断与条件</th></tr></thead><tbody><tr><td>欠拟合是模型未能充分捕捉数据规律</td><td>对</td></tr><tr><td>隐藏层的非线性激活提高网络表达能力</td><td>对</td></tr><tr><td>价值网络只能输入状态，不能输入动作</td><td>错；Q 网络可联合输入状态与动作</td></tr><tr><td>价值网络永远不需要时间信息</td><td>错；有限时域等任务可能需要</td></tr><tr><td>价值函数描述状态转移概率</td><td>错；价值描述期望回报</td></tr><tr><td>学习率越大就越快收敛</td><td>错；过大可震荡、发散</td></tr><tr><td>正确步骤为 d → c → a → e → b</td><td>对；重复的是训练过程而非重新初始化</td></tr><tr><td>MSE 是价值回归的常用损失</td><td>对；不是唯一选择</td></tr><tr><td>MC 用一步 TD 目标作为回归目标</td><td>错；经典 MC 使用完整采样回报</td></tr></tbody></table><p>题目来源：用户提供的三张截图，共 9 题，第 3 题为多选。保留原题关键措辞；第 3 题建议 A、C，并注明时间输入的条件；第 8 题“均方差”按 MSE 解读。答案为独立解答，非官方答案。</p><p>进一步阅读：<a href="https://www.incompleteideas.net/book/bookdraft2018mar21.pdf">Sutton &amp; Barto，第 9 章 On-policy Prediction with Approximation</a>；<a href="https://spinningup.openai.com/en/latest/spinningup/rl_intro.html">价值函数定义与时间依赖</a>；<a href="https://hankyang.seas.harvard.edu/OptimalControlReinforcementLearning/value-rl.html">价值函数近似与半梯度方法</a>。</p></section>'''
